package ui

const AdminEditorStatsCSS = `.editor-stats{display:flex;gap:1rem;flex-wrap:wrap;padding:.65rem 1rem;color:var(--muted);font-size:.78rem}.editor-stats strong{color:var(--ink);font-variant-numeric:tabular-nums}.editor-stats .is-overused{color:var(--red,#dc2626);font-weight:700}`

const AdminEditorStatsJS = `(()=>{const update=()=>{const bar=document.querySelector('[data-editor-stats]');if(!bar)return;const editor=document.querySelector('.richtext-editor .ql-editor,.richtext-editor[contenteditable="true"],textarea[name="body"],textarea[name="description"]');if(!editor){bar.hidden=true;return}bar.hidden=false;const text=editor.value??editor.innerText??editor.textContent??'';const words=text.trim().match(/\S+/gu)||[];bar.querySelector('[data-editor-words]').textContent=String(words.length);bar.querySelector('[data-editor-characters]').textContent=String(text.length);bar.querySelector('[data-editor-reading-time]').textContent=String(Math.max(1,Math.ceil(words.length/200)));const keyword=document.querySelector('[name="focus_keyword"],[name="keyword"]');const wrap=bar.querySelector('[data-editor-keyword-wrap]');if(keyword?.value.trim()){const needle=keyword.value.trim().toLocaleLowerCase();const matches=words.filter(word=>word.replace(/[^\p{L}\p{N}]/gu,'').toLocaleLowerCase()===needle).length;const density=words.length?matches/words.length*100:0;bar.querySelector('[data-editor-keyword-density]').textContent=density.toFixed(1)+'%';wrap.hidden=false;wrap.classList.toggle('is-overused',density>3)}else{wrap.hidden=true;wrap.classList.remove('is-overused')}};document.addEventListener('input',event=>{if(event.target.closest('.richtext-editor,textarea[name="body"],textarea[name="description"],[name="focus_keyword"],[name="keyword"]'))update()});document.addEventListener('hydro:admin-navigated',update);update()})();`
